SELECT EMP0.SAL FROM EMP AS EMP0 LEFT JOIN (SELECT COUNT(*) AS c, COUNT(*) AS ck, NAME FROM DEPT GROUP BY NAME) AS t5 ON EMP0.JOB = t5.NAME LEFT JOIN (SELECT DEPTNO, TRUE AS i, NAME FROM DEPT) AS t6 ON EMP0.EMPNO = t6.DEPTNO AND EMP0.JOB = t6.NAME WHERE t5.c = 0 OR (t6.i IS NOT NULL OR t5.ck < t5.c) IS NOT TRUE
